import{_ as e,c as p,o as r,ah as s}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"23、【剥】 坤下艮上","description":"周易尚氏学 - 23、【剥】 坤下艮上","frontmatter":{"title":"23、【剥】 坤下艮上","description":"周易尚氏学 - 23、【剥】 坤下艮上"},"headers":[],"relativePath":"zh/classics/shangshi/028.md","filePath":"zh/classics/shangshi/028.md"}'),i={name:"zh/classics/shangshi/028.md"};function t(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="_23、【剥】-坤下艮上" tabindex="-1">23、【剥】 坤下艮上 <a class="header-anchor" href="#_23、【剥】-坤下艮上" aria-label="Permalink to “23、【剥】 坤下艮上”">​</a></h1><p>剥候卦。时当九月。阴消阳，柔变刚。杂卦云剥烂也。盖阴消阳。柔变刚。皆以渐而及。非猝然为之。有似于树木老皮之剥落。归藏作仆。仆与扑通。庄子人间世。蚤蚤（上文）仆缘。仆缘即扑缘。扑击也。而幽（内双豕）风八月剥枣。传剥击也。是仆与剥义同也。不利有攸往。谓阴不宜再长也。传曰小人长。阴长则阳消。故往不利。</p><p>彖曰。剥。剥也。柔变刚也。不利有攸往。小人长也。顺而止之。观象也。君子尚消息盈虚。天行也。</p><p>艮为视为观。象失传。详焦氏易诂观卦即顺而止。今一阳在上。下观群阴。仍观象也。剥本消卦。然相对者必息。一消一息。一盈一虚。天道循环本如此。不足异也。</p><p>象曰。山附于地。剥。上以厚下安宅。</p><p>上谓上九。坤为厚为下。艮为宅为安。</p><p>初六。剥床以足，蔑贞，凶。</p><p>初震位。故曰足。以及也。周语。太宰以史祝。管子服制。官吏以命士。盐铁论大论篇。呻吟槁简。诵死人之语。则有司不以文学。以义皆同及。剥床以足。即剥床及足也。艮为床。易林比之贲云。展转空床。内怀忧伤。以贲艮为床也。剥全体民象。故屡言床。虞翻不知此象。以坤消乾初。成巽为床。而惠栋又谓巽为木。坤西南卦。设木于西南奥。乾人藉之。床之象也。故夫一象之失传。可使名家易。迂曲至于如此。真可叹也。蔑释文云。荀作灭。象曰灭下。盖荀之所本。王陶庐云。蔑灭古通。周语而蔑其人民。文选邻里相送方山诗。音尘慰寂蔑。注皆作灭。故王注云犹消也。惟灭属下读。似难为句。灭说文尽也。剥床以足蔑者。言床足被剥尽也。故卜问凶。虞翻下属为句。训为无。谓初失位。故曰蔑贞。谓失正也。然二爻当位。亦曰蔑贞。则不合矣。而清易家多从之。非。</p><p>象曰。剥床以足，以灭下也。</p><p>灭下即释蔑义。</p><p>六二。剥床以辨，蔑贞凶。</p><p>释文云。辨徐音办具之办。足上也。马郑同。薛虞云。膝下也。王弼亦云足上。按马郑王等似皆以二在初上。故云足上。虞翻谓为指间。王引之读为骗（左足）。骗（左足）膝头也。俞越（左木）谓辨通胖。胖胁侧也。似皆未安。按周礼天官小宰六日廉辨。注杜子春云廉辨或作廉端。故贾疏云经本作廉端。是辨端音近通用。端首也。剥床以端。是剥及床头也。剥之而尽故贞凶。</p><h3 id="象曰。剥床以辨-未有与也。" tabindex="-1">象曰。剥床以辨，未有与也。 <a class="header-anchor" href="#象曰。剥床以辨-未有与也。" aria-label="Permalink to “象曰。剥床以辨，未有与也。”">​</a></h3><p>未有与。言上无应。</p><p>六三。剥之，无咎。</p><p>释文一本作剥之无咎。非。按之字。乃从象辞而衍。无者是也。三处五阴之中。独能从善不党于上下二阴。故曰失上下。</p><h3 id="象曰。剥之无咎。失上下也。" tabindex="-1">象曰。剥之无咎。失上下也。 <a class="header-anchor" href="#象曰。剥之无咎。失上下也。" aria-label="Permalink to “象曰。剥之无咎。失上下也。”">​</a></h3><p>六四。剥床以肤。凶。</p><p>四艮体。艮为肤。故曰剥床以肤。足辨肤皆指床言。肤犹言床面也。人卧床。身与床切。剥及于是。故言近灾。自王肃以肤指人身言。岂知剥及人身。则灾及矣。胡得曰近。乃后儒惑之。谓床不能称肤。王引之谓王弼云。剥床之足。剥床之辨详。下文亦可曰剥床之肤乎。夫床既可曰足。曰辨。又何不可称肤。似皆惑于肃说。故拘泥若是。</p><h3 id="象曰。剥床以肤。切近灾也。" tabindex="-1">象曰。剥床以肤。切近灾也。 <a class="header-anchor" href="#象曰。剥床以肤。切近灾也。" aria-label="Permalink to “象曰。剥床以肤。切近灾也。”">​</a></h3><p>六五。贯鱼以官人宠。无不利。</p><p>坤为鱼象失传。详焦氏易估除易林外。后唯郭璞知之。洞林璞筮迁徙。得明夷。曰嗟呼黔黎。时漂异类。桑梓之邦。其为鱼乎。明夷上坤为鱼。为邦。震为桑梓。故曰桑梓之帮。其为鱼乎。剥重坤。故曰贯鱼。艮为宫为宠。以宫人宠者。周礼九嫔注云。女御八十一人当九夕。世妇二十七人当三夕。三夫人当一夕。是天子之宫进御。每夜九人或三人。故曰贯鱼以宫人宠。言宫人之宠御。以次而进。若贯鱼也。即五率群阴以承阳。鱼贯而进也。诗邶风宴尔新婚。不我屑以。笺以用也。以宫人宠。即用宫人宠也。蒙之用说桎告（左木）。益之利用为依迁国。皆与此以字义同也。此与豫九四之朋盍谷簪。皆为易象之最神妙。而最难于形容者。王陶庐云。易辞有非注视卦象不能解者。此等是也。而二千年来。因簪象鱼象之失传。遂改营为音（右戈）为摄。以求与坎象合。命剥五变巽。以求与鱼象合。而易理遂亡于解说矣。杜甫云。盖簪喧枥马。鲍照云。鱼贯度飞梁。皆此二句之确诂。而杜诗尤非真知易者。不敢如此道也。宋蔡弼注社诗。遂误为宴朋友。</p><h3 id="象曰。以宫人宠。终无尤也。" tabindex="-1">象曰。以宫人宠。终无尤也。 <a class="header-anchor" href="#象曰。以宫人宠。终无尤也。" aria-label="Permalink to “象曰。以宫人宠。终无尤也。”">​</a></h3><p>五得承阳。故无尤悔。</p><p>上九。硕果不食。君子得舆。小人剥庐。</p><p>艮为果瓜。硕大也。孤阳在上。故曰硕果。震为食。震覆故不食。震食象失传。详鱼氏易诂卦一阳未消。陕（？）余在上。是其义也。艮为君子。坤为大舆为载。艮在坤上。乘舆之象也。故曰得舆。坤为小人。艮为庐。候卦阴终消阳。故曰剥庐。君子得舆。由上视下取象。小人剥庐。由下视上取象。</p><h3 id="象曰。君子得舆。民所载也。小人剥庐。终不可用也。" tabindex="-1">象曰。君子得舆。民所载也。小人剥庐。终不可用也。 <a class="header-anchor" href="#象曰。君子得舆。民所载也。小人剥庐。终不可用也。" aria-label="Permalink to “象曰。君子得舆。民所载也。小人剥庐。终不可用也。”">​</a></h3><p>坤为民。艮为终。</p>',28)])])}const m=e(i,[["render",t]]);export{_ as __pageData,m as default};
